messages.content:
{"spec_element": "invariant",
 "proof_obligation": "bridge",
 "diagnosis": "The loop invariant only states 0 <= i <= a.Length; the conjunct saying key does not occur at positions 0..i-1 (described by the comment) is missing. Hence at the early return Dafny cannot establish 'forall k :: 0 <= k < i ==> a[k] != key', and after the loop (i == a.Length) it cannot establish that key is absent from a. Adding 'invariant forall k :: 0 <= k < i ==> a[k] != key' lets the invariant plus exit condition imply both postconditions."}
---
   i := 0;
   while (i < a.Length)
     decreases a.Length - i;
     invariant 0 <= i <= a.Length;
     // key is at none of the positions seen so far
     invariant forall k :: 0 <= k < i ==> a[k] != key;
   {
      if (a[i] == key) { return; }
      i := i + 1;
   }
   i := -1;
}

